const gates=[{"labels": ["rear_leaf", "rear_moving_cheek_0", "rear_moving_cheek_1"], "axis": [-1.0, 1.2246467991473532e-16, 0], "pivot": [-4.898587196589413e-16, 54.7808, 30.0]}, {"labels": ["left_leaf", "left_moving_cheek_0", "left_moving_cheek_1"], "axis": [6.123233995736766e-17, -1.0, 0], "pivot": [-74.7808, 2.4492935982947064e-16, 30.0]}, {"labels": ["right_leaf", "right_moving_cheek_0", "right_moving_cheek_1"], "axis": [6.123233995736766e-17, 1.0, 0], "pivot": [74.7808, 2.4492935982947064e-16, 30.0]}];
export const clips={demo:{label:"Custom gates \u2014 nominal 0 to 60 degrees",duration:6,loop:true,update(t,m){
const angle=30*(1-Math.cos(2*Math.PI*t/6));
for(const g of gates) for(const label of g.labels) m.get(label).rotate(g.axis,angle,g.pivot);
}}};
